{
  "id": "github-api-via-shell",
  "severity": "blocking",
  "since": "2026-09-06",
  "scope": "action",
  "failureMessage": "this sandbox proxy-blocks api.github.com, so a shell poll reports \"still running\" until it times out",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)((do|then|else)\\s+)?((curl|wget)\\b[^;&|\\n]*api\\.github\\.com|gh\\s)/",
      "what": "a GitHub read through the shell: \"{match}\"",
      "fix": "read the head sha's check runs with the GitHub MCP tools (pull_request_read get_check_runs, get_check_run)"
    },
    {
      "tool": "Monitor",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)((do|then|else)\\s+)?((curl|wget)\\b[^;&|\\n]*api\\.github\\.com|gh\\s)/",
      "what": "a Monitor polling GitHub through the shell: \"{match}\"",
      "fix": "read the head sha's check runs with the GitHub MCP tools on a rolling backoff; a shell poll here never sees the run finish"
    }
  ]
}
